// Host-side stand-ins for the handful of ESPHome objects the VE.Direct lambdas
// in firmware/esphome_smdc_bridge.yaml touch. Include this, then the header
// generated by extract_esphome_lambdas.py.
//
// In real ESPHome `id(x)` is rewritten by the code generator to the component
// (or, for `globals:`, to its value). Here every id is a plain object of the
// same name and `id(x)` is just `(x)`.
#pragma once

#include <cmath>
#include <cstdarg>
#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <deque>
#include <string>
#include <vector>

namespace smdc_host {
inline uint32_t now_ms = 0;  // ESPHome's millis() is 32-bit, wrap included
inline std::vector<std::string> warnings;
inline std::vector<std::string> infos;

inline std::string format(const char *fmt, ...) {
  char buf[256];
  va_list args;
  va_start(args, fmt);
  vsnprintf(buf, sizeof(buf), fmt, args);
  va_end(args);
  return buf;
}
}  // namespace smdc_host

inline uint32_t millis() { return smdc_host::now_ms; }

#define ESP_LOGW(tag, ...) smdc_host::warnings.push_back(std::string(tag) + ": " + smdc_host::format(__VA_ARGS__))
#define ESP_LOGI(tag, ...) smdc_host::infos.push_back(std::string(tag) + ": " + smdc_host::format(__VA_ARGS__))

// sensor::Sensor - only publish_state() and .state are used.
struct StubSensor {
  float state = NAN;
  bool has_state = false;
  unsigned long publishes = 0;
  void publish_state(float value) {
    state = value;
    has_state = true;
    publishes++;
  }
  bool reporting() const { return has_state && !std::isnan(state); }
};

// uart::UARTComponent - only available() and read_byte() are used. The real
// read_byte() waits (up to 100 ms) when the buffer is empty, so calling it
// without data is recorded as a blocking read.
struct StubUart {
  std::deque<uint8_t> rx;
  unsigned long blocking_reads = 0;
  unsigned long bytes_read = 0;
  int available() { return (int)rx.size(); }
  bool read_byte(uint8_t *data) {
    if (rx.empty()) {
      blocking_reads++;
      return false;
    }
    *data = rx.front();
    rx.pop_front();
    bytes_read++;
    return true;
  }
};

// A `globals:` entry of type uint32_t that also counts how often it is written
// (the parser writes ve_last_valid_ms exactly once per checksum-valid frame).
struct StubGlobalU32 {
  uint32_t value = 0;
  unsigned long writes = 0;
  StubGlobalU32 &operator=(uint32_t v) {
    value = v;
    writes++;
    return *this;
  }
  operator uint32_t() const { return value; }
};

// ids declared in the YAML
inline StubSensor battery_voltage, battery_current, solar_power, battery_soc, solar_voltage, solar_yield_today;
inline StubUart uart_ve_direct;
inline bool ve_frame_seen = false;       // globals: initial_value "false"
inline StubGlobalU32 ve_last_valid_ms;   // globals: initial_value "0"
inline bool ve_stale = false;            // globals: initial_value "false"
inline uint32_t ve_age_anchor_ms = 0;    // globals: initial_value "0"
inline uint64_t ve_age_accum_ms = 0;     // globals: initial_value "0"
inline uint32_t ve_field_ms[6] = {0, 0, 0, 0, 0, 0};                         // globals: type uint32_t[6]
inline bool ve_field_live[6] = {false, false, false, false, false, false};   // globals: type bool[6]

// Must come after every standard header (it would break e.g. std::locale::id).
#define id(x) (x)
